examples.setupTemplate:
var grants by remember {
    mutableStateOf(
        mapOf(
            {{roles.0.id}} to setOf({{grants.viewer.0}}),
            {{roles.1.id}} to setOf({{grants.member.0}}, {{grants.member.1}}),
            {{roles.2.id}} to setOf({{grants.admin.0}}, {{grants.admin.1}}, {{grants.admin.2}}, {{grants.admin.3}}, {{grants.admin.4}}),
            {{roles.3.id}} to setOf({{grants.owner.0}}, {{grants.owner.1}}, {{grants.owner.2}}, {{grants.owner.3}}, {{grants.owner.4}}, {{grants.owner.5}}),
        ),
    )
}

examples.setup:
var grants by remember {
    mutableStateOf(
        mapOf(
            "viewer" to setOf("records.view"),
            "member" to setOf("records.view", "records.edit"),
            "admin" to setOf("records.view", "records.edit", "records.delete", "members.invite", "members.remove"),
            "owner" to setOf("records.view", "records.edit", "records.delete", "members.invite", "members.remove", "billing.manage"),
        ),
    )
}
